import{c as t,Q as n,j as a,m as r}from"./chunks/framework.BqPkuuVc.js";const p=JSON.parse('{"title":"Concepts and glossary","description":"","frontmatter":{},"headers":[],"relativePath":"user/getting-started/concepts-glossary.md","filePath":"user/getting-started/concepts-glossary.md"}'),s={name:"user/getting-started/concepts-glossary.md"};function o(i,e,h,c,d,l){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="concepts-and-glossary" tabindex="-1">Concepts and glossary <a class="header-anchor" href="#concepts-and-glossary" aria-label="Permalink to &quot;Concepts and glossary&quot;">​</a></h1><p><strong>Audience:</strong> Anyone new to orienteering timing, or new to how Manager models it.</p><p>This page defines the orienteering terms and the Manager-specific concepts used throughout the rest of the documentation. You don&#39;t need to read it end to end — skim it now, then come back when a word in another page is unfamiliar. Where a term has a page of its own, the definition links to it.</p><p>Throughout the docs, <em>italic</em> marks a term defined here.</p><h2 id="orienteering-terms" tabindex="-1">Orienteering terms <a class="header-anchor" href="#orienteering-terms" aria-label="Permalink to &quot;Orienteering terms&quot;">​</a></h2><h3 id="the-event-and-its-people" tabindex="-1">The event and its people <a class="header-anchor" href="#the-event-and-its-people" aria-label="Permalink to &quot;The event and its people&quot;">​</a></h3><p><strong>Event</strong> — the top-level container for a competition: its classes, courses, controls, competitors and results all live inside one event. Manager can hold many events; usually one is <em>live</em> at a time, though two can be (see <a href="./../running-the-event/two-events-at-once">Running two events at once</a>).</p><p><strong>Competitor</strong> — an individual participant in the event. See <a href="./../event-setup/competitors-clubs-teams">Competitors, clubs and teams</a>.</p><p><strong>Card number</strong> — the number of the electronic card a competitor carries, recorded on their entry. A card download is matched to its competitor by this number. Two people may share a card if they run at different times. See <a href="./../event-setup/competitors-clubs-teams#card-numbers">Card numbers</a>.</p><p><strong>Hire card</strong> — a card the event lends to a competitor who doesn&#39;t have their own. The pool of hire-card numbers is set up once in <strong>Settings → Hire card registry</strong>; anyone whose card number is in the pool is &quot;on a hire card&quot;, and the download desk is reminded to collect it. See <a href="./../running-the-event/hire-items">Hire items</a>.</p><p><strong>Hire item</strong> — anything else you lend, such as a compass or a map board, set up in <strong>Settings → Other hire registry</strong> and ticked on the competitor who has it. See <a href="./../running-the-event/hire-items#everything-else-you-lend">Hire items</a>.</p><p><strong>Bib</strong> — the number a competitor wears. Can be allocated in blocks by class, and kept the same across the days of a carnival. See <a href="./../event-setup/bib-numbers">Bib numbers</a>.</p><p><strong>IOF ID</strong> — a competitor&#39;s id in the IOF&#39;s athlete database, used to match people in IOF XML files and the world ranking. See <a href="./../event-setup/import-event-data#importing-iof-ids">Importing IOF IDs</a>.</p><p><strong>Club</strong> — the organisation a competitor represents. Clubs are reused across events through the <a href="./../reference/club-registry">Club Registry</a>; competitors can be reused through the <a href="./../reference/competitor-registry">Competitor Registry</a>.</p><p><strong>Class</strong> — the category a competitor enters, such as <strong>M21E</strong> (Men, 21, Elite) or <strong>W18A</strong> (Women, 18, A-grade). Everyone in a class is ranked against each other. A class is assigned one or more <em>courses</em>. See <a href="./../event-setup/classes-and-courses">Classes and courses</a>.</p><p><strong>Course pool</strong> — a class with more than one course, where each competitor runs <em>one</em> of them and their card is checked against each until one fits. See <a href="./../event-setup/classes-and-courses#course-pools-and-locking-a-competitor-to-a-course">Course pools</a>.</p><p><strong>Multi-part class (Duo)</strong> — a class whose competitors run <em>all</em> its courses, one after another on one card, without coming back to the finish in between, for one combined result — a Duo class at an MTBO is a score ride and then a score run. In the <strong>Edit Class</strong> dialog it is <strong>Competitors do → All courses</strong>; each boundary between two parts is a <em>changeover</em>. See <a href="./../event-setup/classes-and-courses#classes-whose-competitors-do-every-course">Classes whose competitors do every course</a>.</p><p><strong>Changeover</strong> — the point where one part of a race ends and the next begins: in a relay, where one leg&#39;s runner hands over to the next; in a multi-part class, the control whose punch ends one course and starts the next.</p><p><strong>Ranking</strong> — a competitor&#39;s place on an external ranking list drawn up before the event: a national ranking, a squad&#39;s seeding order, whatever list you were handed. <strong>1 is the best-ranked athlete</strong> and the number gets worse as it grows; someone who isn&#39;t on the list has no ranking at all. It is a <em>place</em>, not a points score — Manager never treats a bigger number as better. Its main use is seeding a <a href="./../event-setup/start-draw#drawing-by-ranking">start draw</a>. Nothing to do with a competitor&#39;s finishing position, which Manager works out from the results. See <a href="./../event-setup/competitors-clubs-teams#ranking">Ranking</a>.</p><h3 id="the-course-and-the-controls" tabindex="-1">The course and the controls <a class="header-anchor" href="#the-course-and-the-controls" aria-label="Permalink to &quot;The course and the controls&quot;">​</a></h3><p><strong>Course</strong> — the physical route a competitor runs: an ordered chain of controls from a <em>start</em> to a <em>finish</em>. Several classes can share one course. See <a href="./../event-setup/classes-and-courses">Classes and courses</a>.</p><p><strong>Control</strong> — a single timing point at a position on the map. A normal control carries a <strong>control code</strong> (the number printed on it and programmed into its unit, e.g. <em>131</em>), which is how a punch is matched to it. See <a href="./../event-setup/controls-and-radio-controls">Controls and radio controls</a>.</p><p><strong>Start, finish, check</strong> — special controls that mark, respectively, where timing begins, where it ends, and where competitors confirm their card is clear before starting. Unlike normal controls these are <strong>codeless</strong> — they describe a place on the map, not a code. An event can have <strong>several</strong> of each (e.g. <em>Start 1</em> and <em>Start 2</em> at different locations), and each course picks which start and finish it chains through. A course can also use its first numbered control as its start, or its last as its finish — see <a href="./../event-setup/classes-and-courses#starting-or-finishing-at-a-numbered-control">Starting or finishing at a numbered control</a>.</p><p><strong>Punch</strong> — the record that a competitor visited a control. Most punches are <strong>electronic</strong>, written to the competitor&#39;s <em>card</em> either by touching the unit (<em>contact</em>) or by SIAC &quot;air&quot; punching (<em>contactless</em>). A <strong>manual</strong> or pin punch is the needle-and-paper backup used when the electronics fail; to accept one, mark the control visited on the competitor (see <a href="./../running-the-event/resolving-issues#competitor-results">Resolving issues on the day</a>).</p><p><strong>Split</strong> — the time recorded at an intermediate control, used to show how a competitor&#39;s run is progressing and to compare sections of the course between competitors.</p><p><strong>Leg</strong> — the section of a course between two consecutive controls. Its length is the <em>leg distance</em>, shared by every course that runs it, and a leg can carry an untimed allowance for a road crossing. (In a relay, <em>leg</em> also means one team member&#39;s whole portion of the team&#39;s course — see below.) See <a href="./../event-setup/classes-and-courses#leg-distances">Leg distances</a>.</p><p><strong>Course format</strong> — how a course is scored: a <strong>Line</strong> course is visited in order; a <strong>Scatter</strong> course needs a set number of its controls, in any order; a <strong>Score</strong> course collects points from any of its controls, in any order, usually against a time limit with points deducted for finishing late. See <a href="./../event-setup/classes-and-courses#score-and-scatter-courses">Score and scatter courses</a>.</p><p><strong>Variations (forking)</strong> — versions of one course that differ in a few legs, so that runners starting together split up. Each competitor or relay team is given a variation. See <a href="./../event-setup/classes-and-courses#combining-forked-courses-into-variations">Combining forked courses into variations</a>.</p><p><strong>Course with loops</strong> — a course whose loops all start and end at one <em>common control</em>, run in any order as long as every loop is run: a butterfly for a single runner, or a <em>star relay</em> where a team shares the loops. See <a href="./../event-setup/classes-and-courses#courses-with-loops">Courses with loops</a> and <a href="./../event-setup/star-relays">Star relays</a>.</p><p><strong>Check punch</strong> — a punch at the <strong>Check</strong> unit near the start, before the start itself. It doesn&#39;t start anybody: Manager marks the runner <strong>checked in</strong> and counts them on the On course list until something says they&#39;re back, which is why a check-in matters for safety. See <a href="./../running-the-event/safety-check">Safety check</a>.</p><h3 id="relays-and-teams" tabindex="-1">Relays and teams <a class="header-anchor" href="#relays-and-teams" aria-label="Permalink to &quot;Relays and teams&quot;">​</a></h3><p><strong>Relay team</strong> — a team whose members each run one <em>leg</em> of the course in sequence, handing over to the next runner. The team&#39;s result is the sum of its legs. See <a href="./../event-setup/relay-events">Relay events</a>.</p><p><strong>Star relay</strong> — a relay in which every leg goes out from one central control and comes back to it, the team&#39;s runners taking turns to run the loops of one course. See <a href="./../event-setup/star-relays">Star relays</a>.</p><h3 id="starts-and-finishing" tabindex="-1">Starts and finishing <a class="header-anchor" href="#starts-and-finishing" aria-label="Permalink to &quot;Starts and finishing&quot;">​</a></h3><p><strong>Allocated start</strong> — a start time set in advance: for one competitor (from the <em>start draw</em>, an import or by hand), for a whole class (a <em>class mass start</em>), or for the whole event (an <em>event mass start</em>). See <a href="./../event-setup/start-times">Start times</a>.</p><p><strong>Mass start</strong> — everyone in a class, or the whole event, starting together at one time. A relay always has one. See <a href="./../event-setup/start-times#event-mass-start">Start times</a>.</p><p><strong>Punched start</strong> — the start time recorded when a competitor punches a Start unit, as at a start-when-ready event. When a competitor has both an allocated time and a punched start, a setting decides which wins. See <a href="./../event-setup/start-times#punched-starts">Punched starts</a>.</p><p><strong>Start draw</strong> — working out each competitor&#39;s allocated start time, class by class, across the start lanes. See <a href="./../event-setup/start-draw">Drawing start times</a>.</p><p><strong>Course closure</strong> — the time of day by which every competitor must be back. When it passes, anyone still out becomes <strong>Overtime</strong> and anyone never seen becomes <strong>DNS</strong>. See <a href="./../running-the-event/safety-check#course-closure-settling-the-list-at-a-set-time">Course closure</a> and <a href="./../reference/status-and-race-time">Status and race time rules</a>.</p><p><strong>Safety check</strong> — accounting for everyone who went out: making the On course list go to zero by downloads, station reads and decisions. See <a href="./../running-the-event/safety-check">Safety check</a>.</p><h3 id="multi-stage-events-carnivals" tabindex="-1">Multi-stage events (carnivals) <a class="header-anchor" href="#multi-stage-events-carnivals" aria-label="Permalink to &quot;Multi-stage events (carnivals)&quot;">​</a></h3><p><strong>Multi-stage event</strong> — one competition decided over several races: an Easter 3 Days, a summer carnival, a league. Each race is an ordinary event; the multi-stage event is the container that combines them. Often called a <em>carnival</em>.</p><p><strong>Stage</strong> — one race of a multi-stage event, numbered from 1.</p><p><strong>Standings</strong> — the combined result across the stages: each competitor&#39;s per-stage contributions, a total, and an overall position.</p><p><strong>Chasing start</strong> (or <em>pursuit start</em>) — a start list for a later stage where everyone starts at their deficit behind the overall leader, so the first across the line wins.</p><p>See <a href="./../event-setup/multi-stage-events">Multi-stage events</a>.</p><h3 id="knock-out-competitions" tabindex="-1">Knock-out competitions <a class="header-anchor" href="#knock-out-competitions" aria-label="Permalink to &quot;Knock-out competitions&quot;">​</a></h3><p><strong>Knock-out competition</strong> — the other kind of multi-stage event: a sequence of rounds where each round&#39;s field comes from the results of the round before, rather than stages added up. Competitors enter once, into the first round.</p><p><strong>Round</strong> — one phase of a knock-out — Qualification, Quarter Finals, Finals. A round <em>is</em> a stage, and therefore an ordinary event. Rounds run one at a time.</p><p><strong>Heat</strong> — one simultaneously-run group within a round. A heat <em>is</em> a class in that round&#39;s event, with its own course and its own mass start. An A final and a B final are two heats of the Finals round, not two rounds.</p><p><strong>Advancement</strong> — working out a round&#39;s field from an earlier round&#39;s results and writing the entries in. Always previewed, never automatic, and safe to run twice.</p><p><strong>Lucky loser</strong> — somebody who advances on their time across all the heats rather than on their place within one.</p><p><strong>Classification</strong> — the overall knock-out result: how far each competitor got, then where they finished in that round.</p><p>See <a href="./../event-setup/knock-out-competitions">Knock-out competitions</a>.</p><h3 id="competitor-status" tabindex="-1">Competitor status <a class="header-anchor" href="#competitor-status" aria-label="Permalink to &quot;Competitor status&quot;">​</a></h3><p>Every competitor has a <strong>status</strong> that Manager works out automatically as start times pass, punches arrive and cards are downloaded. The common ones:</p><table tabindex="0"><thead><tr><th>Shown as</th><th>Meaning</th></tr></thead><tbody><tr><td><em>(blank)</em></td><td><strong>None</strong> — no result yet.</td></tr><tr><td><strong>On course</strong></td><td>Started but not yet finished (the orienteering term <em>In Forest</em>).</td></tr><tr><td><strong>OK</strong></td><td>Finished with a valid result.</td></tr><tr><td><strong>MP</strong></td><td>Missing Punch — a required control wasn&#39;t punched.</td></tr><tr><td><strong>DNF</strong></td><td>Did Not Finish.</td></tr><tr><td><strong>DNS</strong></td><td>Did Not Start.</td></tr></tbody></table><p>There are several more: <strong>DSQ</strong> (Disqualified), <strong>OVT</strong> (Overtime — still out at the course closure), <strong>OOC</strong> (Out of competition), <strong>NT</strong> (No timing), <strong>NP</strong> (Not competing) and <strong>CAN</strong> (Cancelled). For the full list and the rules behind every transition, see <a href="./../reference/status-and-race-time">Status and race time rules</a>.</p><p><strong>Provisional result</strong> — an <strong>OK</strong> worked out from a radio finish before the card has been downloaded. It is shown with a <code>*</code> and may still change; the card download makes it final. The competitors waiting for that download are the <strong>Pending</strong> count on the dashboard. See <a href="./../reference/status-and-race-time#provisional-vs-final-ok">Provisional vs final OK</a> and <a href="./../running-the-event/who-is-still-on-course">Seeing who is still on course</a>.</p><p><strong>Sub-second timing</strong> — whether an event separates runners by fractions of a second. Off by default: a whole second is the finest difference, and two finishers inside the same second share a place. See <a href="./../reference/status-and-race-time">Status and race time rules</a>.</p><h2 id="mesho-manager-concepts" tabindex="-1">meshO Manager concepts <a class="header-anchor" href="#mesho-manager-concepts" aria-label="Permalink to &quot;meshO Manager concepts&quot;">​</a></h2><p><strong>Server / workstation</strong> — you run Manager on one computer (the <strong>server</strong>); everyone else joins from a browser on the same network. There&#39;s no per-machine install. Event data lives in Manager itself — there&#39;s no separate database — and arrives through imports, manual entry, card downloads and radio punches. See <a href="./../what-is-mesho-manager/">What is meshO Manager?</a>.</p><p><strong>Computer</strong> — every browser that opens Manager is a <em>computer</em> to it, and can be given a name (&quot;Download lane A&quot;) the first time it opens Manager. The name shows in the <a href="./../reference/audit-trail#computers">audit trail</a>, and each computer has its own choice of where the splits and labels for cards read on it print. See <a href="./../running-the-event/splits-printing#where-each-computer-s-splits-and-labels-print">Where each computer&#39;s splits and labels print</a>.</p><p><strong>Access links</strong> — the ready-made links to each part of Manager, by the server&#39;s name and by its IP address, in <strong>Settings → Server</strong>. See <a href="./../reference/server-addresses">Reaching the server: name or IP</a>.</p><p><strong>Access PIN</strong> — an optional PIN, set in <strong>Settings → Access protection</strong>, that the manager screens and the registration desk ask for. The spectator site, the kiosk and the arena screens stay open to everyone. See <a href="./../reference/settings#access-protection">Settings</a>.</p><p><strong>HTTPS</strong> — a secure link to the server. A laptop other than the server needs it to use a card reader in the browser. See <a href="./../reference/https-and-certificates">HTTPS and certificates</a>.</p><p><strong>Live standby</strong> — a second computer running Manager that keeps a live copy of the running event and can <strong>Take over</strong> if the main computer fails. Taking over is always your decision. See <a href="./../running-the-event/live-standby">Live standby</a>.</p><h3 id="the-life-of-an-event" tabindex="-1">The life of an event <a class="header-anchor" href="#the-life-of-an-event" aria-label="Permalink to &quot;The life of an event&quot;">​</a></h3><p>An event moves through three modes, and what you can do depends on which it&#39;s in:</p><ul><li><strong>Setup</strong> — the event is being built. You configure classes, courses, controls, competitors and start times. Downloads and live results don&#39;t happen yet. The status chip reads <strong>Setup</strong>.</li><li><strong>Live</strong> — the event is running. Card downloads work, radio punches flow in, and results calculate in real time. The event date locks, but competitors, classes and start times stay editable so late entries and corrections still work. You enter this with <strong>Start event</strong> and leave it with <strong>Finish event</strong>. The chip reads <strong>Live</strong>. Two events can be live at once — see <a href="./../running-the-event/two-events-at-once">Running two events at once</a>.</li><li><strong>Archive</strong> — the event has been finished. The data remains for results and exports. The chip reads <strong>Complete</strong>. Finishing isn&#39;t final: <strong>Restart event</strong> takes a finished event live again, on any later day, for the competitor who turns up after you&#39;ve closed it off.</li></ul><p>(Two exception states exist: an event left running when Manager closed shows as <strong>Interrupted</strong> and can be resumed, and one you choose not to resume becomes <strong>Abandoned</strong>. Both can be resumed or marked finished at any time.) See the <a href="./first-event-walkthrough">first-event walkthrough</a> for the lifecycle in practice, and <a href="./../running-the-event/dashboard#restarting-an-event-you-ve-already-finished">the dashboard</a> for restarting.</p><p><strong>Test mode</strong> — starting an event dated in the future runs it in test mode, for practising and checking a setup. See <a href="./../running-the-event/dashboard">The event dashboard</a>.</p><p><strong>Low-key event</strong> — an event with no entries beforehand, such as a club training, where Manager creates competitors and courses from the cards as they&#39;re downloaded. See <a href="./../event-setup/low-key-events">Low-key events</a>.</p><p><strong>Results quarantine</strong> — holding back chosen classes&#39; results from every public display until you release them, so runners waiting in a start quarantine learn nothing about the course. The start list stays visible. See <a href="./../event-setup/results-quarantine">Results quarantine</a>.</p><h3 id="how-timing-data-arrives" tabindex="-1">How timing data arrives <a class="header-anchor" href="#how-timing-data-arrives" aria-label="Permalink to &quot;How timing data arrives&quot;">​</a></h3><p><strong>Card</strong> — the electronic timing chip a competitor carries (a SportIdent or EMIT card). It records a punch at each control. &quot;SI card&quot; refers specifically to the SportIdent brand.</p><p><strong>Card download</strong> — reading a finished competitor&#39;s card at the download desk. This produces the <strong>authoritative</strong> result — the full set of punches, evaluated against the course. See <a href="./../running-the-event/card-download">Downloading cards</a>.</p><p><strong>Unknown card</strong> — a card that isn&#39;t recorded against any competitor. A download from one arrives <strong>Unassigned</strong>, waiting for you to give it to a competitor or enter a new one. See <a href="./../running-the-event/card-download">Downloading cards</a>.</p><p><strong>Station</strong> — a SportIdent unit: a control, start, finish or check unit, or the reader at the download desk. Every control unit keeps a memory of the cards that punched it, which can be read into Manager (<strong>Station memory</strong>) and its settings changed (<strong>SportIdent station</strong>). See <a href="./../running-the-event/station-memory">Station memory</a> and <a href="./../reference/station-configuration">Station configuration</a>.</p><p><strong>Download station</strong> — a meshO unit that reads cards and sends them to the server over the radio network, with no computer beside it. See <a href="./../running-the-event/splits-printing#cards-read-over-the-radio-network">Cards read over the radio network</a>.</p><p><strong>Radio punch</strong> — a punch sent to Manager <strong>live</strong> over radio as the competitor passes a control, rather than waiting for their card to be downloaded at the finish. Radio punches drive the live picture; the card download confirms it later. See <a href="./../running-the-event/radio-punches">Radio punches</a>.</p><p><strong>Radio control</strong> — a control whose unit reports punches live (via meshO Prime or SIRAP), so runners&#39; progress appears on the spectator site, the Leaderboard and Commentary as they pass. A class&#39;s radio controls form an <strong>ordered sequence</strong> (radio 1, radio 2, …), and Manager identifies each split by its <strong>position</strong> in that sequence rather than by the control&#39;s code — the same code can appear more than once in a course (for example a butterfly or loop passed twice), so the code alone wouldn&#39;t say which passing it was. See <a href="./../event-setup/controls-and-radio-controls">Controls and radio controls</a>.</p><p><strong>Event map</strong> — the map image you upload on the <strong>Map</strong> page and <em>calibrate</em> to real-world positions. It is the background of the live map, and the <strong>Radio control placement</strong> screen uses it to plan which controls carry a radio and whether each can reach meshO Prime. See <a href="./../event-setup/event-map-and-radio-placement">The event map and radio placement</a>.</p><p><strong>meshO Prime</strong> — the field-unit hardware that receives punches from radio controls and feeds them to the server. It plugs into the server computer over USB. See <a href="./../running-the-event/connecting-prime-and-radios">Connecting meshO Prime and radios</a>.</p><p><strong>Field unit</strong> — any meshO device on the radio network: meshO Prime, the meshO Control units at radio controls, and meshO Athlete units, the GPS trackers some competitors carry. See <a href="./../running-the-event/tracking">Tracking</a>.</p><p><strong>SIRAP</strong> — a common format for sending punches between timing systems over the network. Manager can forward its radio punches to other software, and accept punches from it. See <a href="./../running-the-event/radio-punches#forwarding-and-receiving-punches">Forwarding and receiving punches</a>.</p><p><strong>Replay (test mode)</strong> — a training and testing tool that replays captured event data so you can practise or check a setup without a real event. It&#39;s not something you use during a live event. See <a href="./../running-the-event/dashboard">The event dashboard</a>.</p><h3 id="screens-and-views" tabindex="-1">Screens and views <a class="header-anchor" href="#screens-and-views" aria-label="Permalink to &quot;Screens and views&quot;">​</a></h3><p><strong>Operator UI</strong> — the Manager admin app the event team uses: dashboard, competitors, downloads, settings and so on. This is what most of these docs describe.</p><p><strong>Screens</strong> — the read-only public displays you open in their own browser windows and share to TVs, tablets and phones. Each arena screen shows what you tell it to — a <strong>Leaderboard</strong>, <strong>Live top 10</strong>, an analysis wall or the <strong>Start times</strong>. Alongside them sit the <strong>Commentary</strong> view for the announcer and the <strong>spectator site and kiosk</strong> for the crowd. See <a href="./../screens/creating-screens">Creating screens</a>.</p><p><strong>Leaderboard vs Results</strong> — the <strong>Leaderboard</strong> is the live standings: shown on arena screens, and on Manager&#39;s own <strong>Leaderboard</strong> page under <strong>Event live</strong>. The <strong>Results</strong> page is the operator-facing view of the same data, where you publish and export official results. See <a href="./../screens/leaderboard">Leaderboard</a> and <a href="./../after-the-event/results">Results</a>.</p><p><strong>Spectator / Kiosk</strong> — the public, self-serve views where competitors and spectators look up start lists, live progress, splits and results from their own device or an arena kiosk. See <a href="./../screens/spectator-site-and-kiosk">The spectator site and kiosk</a>.</p><p><strong>Info screens</strong> — view-only displays propped up around the event at <code>/info</code>: a start clock, the upcoming starters, the punches at a radio control, who still has to download, and camera video. See <a href="./../screens/info-screens">Event info screens</a>.</p><p><strong>Registration desk</strong> — a cut-down Manager at <code>/rego</code> for the entry table: finding and entering competitors, fixing classes and cards, and handing out hire cards. See <a href="./../running-the-event/registration-desk">The registration desk</a>.</p><p><strong>Splits print</strong> — the slip printed for a competitor when their card is read. A <strong>result label</strong> is a separate, smaller label for the results board. See <a href="./../running-the-event/splits-printing">Printing splits</a>.</p><h3 id="data-in-and-out" tabindex="-1">Data in and out <a class="header-anchor" href="#data-in-and-out" aria-label="Permalink to &quot;Data in and out&quot;">​</a></h3><p><strong>Eventor</strong> — the online entry and results system many federations use. Manager can create events from it, import entries and start times, and upload results. See <a href="./../event-setup/create-event-from-eventor">Creating an event from Eventor</a>.</p><p><strong>IOF XML</strong> — the international standard file format for orienteering courses, entries, start lists and results. See <a href="./../event-setup/import-event-data">Importing event data</a> and <a href="./../after-the-event/exports">Exporting data</a>.</p><p><strong>OJSON</strong> — Orienteering JSON, meshO&#39;s published file format for event data, with room for what IOF XML can&#39;t express (fractions of a second, how a course is scored). Every import accepts it, and results export to it alongside IOF XML. See <a href="./../advanced/orienteering-json">OJSON</a>.</p><p><strong>Purple Pen</strong> — course-setting software whose <code>.ppen</code> files Manager imports directly. See <a href="./../event-setup/import-event-data#importing-from-purple-pen">Importing from Purple Pen</a>.</p><p><strong>liveresultat</strong> — liveresultat.orientering.se, a public live-results website that Manager can publish to while the event is live. See <a href="./../running-the-event/publishing-live-results#publishing-to-liveresultat">Publishing live results online</a>.</p><p><strong>Cloud sync</strong> — publishing an event to a meshO Manager on the internet, so spectators can browse it online — by default the meshO cloud at events.mesho.live, once the event is finished. See <a href="./../running-the-event/publishing-live-results#publishing-to-the-mesho-cloud">Publishing live results online</a>.</p><p><strong>Backup</strong> — a copy of a whole event in one file, taken by hand, automatically while the event runs, or onto an external drive, and restorable as a new event. See <a href="./../reference/backup-and-restore">Backup and restore</a>.</p><p><strong>Audit trail</strong> — the record of every change made to an event: what changed, when, from where and on which computer. See <a href="./../reference/audit-trail">Audit trail</a>.</p><p><strong>Changes report</strong> — the changes made to people during an event (new cards, class changes), ready to carry into the next events and the competitor registry. See <a href="./../after-the-event/changes-report">Changes report</a>.</p><p><strong>AI assistants (MCP)</strong> — an optional connection that lets an AI assistant read the live event and, if you allow it, make corrections. See <a href="./../reference/ai-assistants-mcp">AI assistants (MCP)</a>.</p><h3 id="extending-manager" tabindex="-1">Extending Manager <a class="header-anchor" href="#extending-manager" aria-label="Permalink to &quot;Extending Manager&quot;">​</a></h3><p><strong>Extensions</strong> — optional add-ons you install at runtime to add custom tiles and features (for example a dashboard tile). They&#39;re a power-user feature, separate from Manager&#39;s built-in functionality. See <a href="./../advanced/installing-extensions">Installing extensions</a>.</p><h3 id="what-s-shared-vs-per-event" tabindex="-1">What&#39;s shared vs per-event <a class="header-anchor" href="#what-s-shared-vs-per-event" aria-label="Permalink to &quot;What&#39;s shared vs per-event&quot;">​</a></h3><p>Most data — competitors, classes, courses, results — belongs to <strong>one event</strong>. A few things are <strong>shared across all your events</strong>: the <a href="./../reference/club-registry">Club Registry</a> and <a href="./../reference/competitor-registry">Competitor Registry</a> (so you can reuse known clubs and people), the <strong>Hire card registry</strong> and <strong>Other hire registry</strong> (what you lend — see <a href="./../running-the-event/hire-items">Hire items</a>), and your app-wide <a href="./../reference/settings">Settings</a>. Editing a shared registry affects every event that draws on it; editing event data affects only that event.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../what-is-mesho-manager/">What is meshO Manager?</a> — the architecture these terms sit in</li><li><a href="./first-event-walkthrough">Walkthrough: your first event</a> — the concepts in action, end to end</li><li><a href="./../reference/status-and-race-time">Status and race time rules</a> — the full status list and the rules behind it</li></ul>',112)])])}const u=t(s,[["render",o]]);export{p as __pageData,u as default};
